'use client';

import * as React from 'react';
import { Select as SelectPrimitive } from '@base-ui/react/select';
import { CheckIcon } from '@phosphor-icons/react';
import { cva, type VariantProps } from 'class-variance-authority';

import { cn } from '@/registry/lib/utils';

// TODO: wrap the Base UI primitive for context-menu if it is not Select, and fill in the variant classes
const contextMenuVariants = cva(
  'relative isolate z-50 max-h-(--available-height) w-(--anchor-width) min-w-36 origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-md bg-overlay p-1 text-primary shadow-md ring-1 ring-line duration-100 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95',
  {
    variants: {
      variant: {
        soft: '',
        solid: '',
      },
    },
    defaultVariants: {
      variant: 'soft',
    },
  }
);

type Variant = 'soft' | 'solid';
type Theme = 'gray' | 'accent' | (string & {});

interface ContextMenuContextValue {
  variant: Variant;
  theme: Theme;
}

const ContextMenuContext = React.createContext<ContextMenuContextValue>({
  variant: 'soft',
  theme: 'gray',
});

const ContextMenu = SelectPrimitive.Root;

function ContextMenuValue({ className, ...props }: SelectPrimitive.Value.Props) {
  return (
    <SelectPrimitive.Value
      data-slot="context-menu-value"
      className={cn('flex flex-1 text-left', className)}
      {...props}
    />
  );
}

function ContextMenuTrigger(props: SelectPrimitive.Trigger.Props) {
  return <SelectPrimitive.Trigger data-slot="context-menu-trigger" {...props} />;
}

function ContextMenuContent({
  className,
  children,
  side = 'bottom',
  sideOffset = 4,
  align = 'center',
  variant = 'soft',
  theme = 'gray',
  ...props
}: SelectPrimitive.Popup.Props &
  Pick<SelectPrimitive.Positioner.Props, 'align' | 'side' | 'sideOffset'> &
  VariantProps<typeof contextMenuVariants> & {
    theme?: Theme;
  }) {
  const context = { variant: variant ?? 'soft', theme };
  return (
    <ContextMenuContext.Provider value={context}>
      <SelectPrimitive.Portal>
        <SelectPrimitive.Positioner
          side={side}
          sideOffset={sideOffset}
          align={align}
          className="isolate z-50"
        >
          <SelectPrimitive.Popup
            data-slot="context-menu-content"
            data-variant={variant}
            data-theme={theme !== 'gray' ? theme : undefined}
            className={cn(contextMenuVariants({ variant }), className)}
            {...props}
          >
            <SelectPrimitive.List>{children}</SelectPrimitive.List>
          </SelectPrimitive.Popup>
        </SelectPrimitive.Positioner>
      </SelectPrimitive.Portal>
    </ContextMenuContext.Provider>
  );
}

function ContextMenuItem({ className, children, ...props }: SelectPrimitive.Item.Props) {
  const { variant } = React.useContext(ContextMenuContext);

  return (
    <SelectPrimitive.Item
      data-slot="context-menu-item"
      data-variant={variant}
      className={cn(
        'relative flex h-7 w-full cursor-default items-center gap-1.5 rounded-(--menu-item-radius) pr-8 pl-1.5 text-sm outline-hidden select-none',
        'data-highlighted:bg-interactive',
        'data-disabled:pointer-events-none data-disabled:opacity-50',
        className
      )}
      {...props}
    >
      <SelectPrimitive.ItemText className="flex flex-1 shrink-0 gap-2 whitespace-nowrap">
        {children}
      </SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator
        render={
          <span className="pointer-events-none absolute right-2 flex size-4 items-center justify-center">
            <CheckIcon className="pointer-events-none" />
          </span>
        }
      />
    </SelectPrimitive.Item>
  );
}

export {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
  ContextMenuValue,
  contextMenuVariants,
};
